from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class DnsParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        dns_ip = self.enb_ent_config.get('dns_ip')
        if dns_ip:
            self.set_parameter('serverIpAddressPrimary', dns_ip)
        else:
            self.set_parameter('serverIpAddressPrimary', '1.1.1.1')
